mapper.select:
SELECT c.*, s.name AS school_name, g.name AS grade_name, t.name AS head_teacher_name, (SELECT COUNT(1) FROM student st WHERE st.class_id = c.id AND st.deleted = 0) AS student_count FROM class_info c LEFT JOIN school s ON c.school_id = s.id LEFT JOIN grade g ON c.grade_id = g.id LEFT JOIN teacher t ON c.head_teacher_id = t.id WHERE c.deleted = 0
AND c.school_id = #{query.schoolId}
AND c.grade_id = #{query.gradeId}
AND c.name LIKE CONCAT('%', #{query.name}, '%')
AND c.head_teacher_id = #{query.headTeacherId}
AND c.status = #{query.status}
ORDER BY c.sort ASC, c.class_num ASC

SELECT id, school_id, grade_id, name, code, class_num FROM class_info WHERE grade_id = #{gradeId} AND deleted = 0
AND status = #{status}
ORDER BY sort ASC, class_num ASC

SELECT c.id, c.school_id, c.grade_id, c.name, c.code, c.class_num, g.name AS grade_name FROM class_info c LEFT JOIN grade g ON c.grade_id = g.id WHERE c.school_id = #{schoolId} AND c.deleted = 0
AND c.status = #{status}
ORDER BY g.grade_num ASC, c.class_num ASC
